vec3 erot(vec3 p,vec3 ax,float t){return mix(dot(ax,p)*ax,p,cos(t))+cross(ax,p)*sin(t);}
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = (fragCoord-.5*iResolution.xy)/iResolution.y;

   vec3 col = vec3(0);

  vec3 ro=vec3(0.5,0.5,-5),rt=vec3(0);
  ro=erot(ro,normalize(vec3(0,1,0)),iTime*.25);

  vec3 z = normalize(rt-ro),x=vec3(z.z,0,-z.x);
  vec3 rd =mat3(x,cross(z,x),z)*normalize(vec3(uv,1.0));
  for(float i=0.,e=0.,g=0.;i++<99.;){

       vec3 p= ro+rd*g;
      p=erot(p,normalize(normalize(vec3(1,-.7,.5))),iTime*.25);
     vec3 op=p;
       float h = length(p)-1.43;    
     p+=cross(sin(p*4.),cos(p.yzx*2.+iTime));

     p=erot(p,vec3(0,0,1),p.z*.5);
    p= abs(p)-.1;

     p=erot(p,vec3(0,0,1),op.z*.5);


        h= mix(h, (min(length(p.xy),min(length(p.yz),length(p.xz)))-.1)/4.,smoothstep(-.2,.2,sin(iTime-length(op)*.1)));
      h = max(length(op)-3.,h);


       g+=e=max(.001,h/1.5);
      col+=(mod(floor(p.z*10.)+floor(p.x*10.)+floor(p.y*10.),2.)*.2+.8)*mix(vec3(.95,.4,.2).bgr*.2,vec3(.95,.4,.2),length(sin(p+iTime)*5.))*.125/exp(2.*i*i*e);
      col= clamp(col,vec3(0),vec3(1)); 

    }
col =sqrt(col);  
   col += cross(sin(col*20.),cos(col.yzx*30.))*.1;

    // Output to screen
    fragColor = vec4(col,1.0);
}
